package br.com.example.davidarchanjo.controller; import br.com.example.davidarchanjo.model.domain.*; import br.com.example.davidarchanjo.model.dto.*; import br.com.example.davidarchanjo.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import javax.validation.Valid; import java.time.*; import java.util.*; @RestController @RequestMapping("/api/v1/scraps") @RequiredArgsConstructor public class ScrapController { private final ScrapRepository scraps; private final PaymentRepository payments; @PostMapping public ResponseEntity<?> create(@Valid @RequestBody ScrapRequest r){if(!Boolean.TRUE.equals(r.getVehicle().getTotalLoss()))return ResponseEntity.badRequest().body(Collections.singletonMap("message","Vehicle must be total loss"));Payment p=payments.findTopByLenderIdOrderByIdDesc(r.getLender().getLenderId()).orElseThrow(()->new IllegalArgumentException("Payment not completed"));if(!"SUCCESS".equals(p.getStatus()))return ResponseEntity.badRequest().body(Collections.singletonMap("message","Payment not completed"));String id=String.format("SCRAP-%d-%06d",Year.now().getValue(),scraps.count()+1);Scrap s=Scrap.builder().scrapId(id).status("SCRAP_APPROVED").customerId(r.getCustomer().getCustomerId()).vehicleId(r.getVehicle().getVehicleId()).vin(r.getVehicle().getVin()).lenderId(r.getLender().getLenderId()).paymentId(p.getPaymentId()).createdAt(Instant.now()).build();scraps.save(s);return ResponseEntity.status(201).body(ScrapResponse.builder().scrapId(id).status(s.getStatus()).customerId(s.getCustomerId()).vehicleId(s.getVehicleId()).paymentId(s.getPaymentId()).createdAt(s.getCreatedAt()).build());} }
